{
  "quantity": {
    "description": "Change in own-team expected single-game scoring margin from adopting the strategy",
    "units": "points",
    "support": "unbounded real; positive favors own team"
  },
  "strategies": [
    {
      "bucket": "analytics",
      "type": "game_management",
      "title": "Model-Guided Fourth-Down Aggression",
      "recommendation": "Use a calibrated win-probability model as the default authority on fourth downs, including decisions in your own territory, and override it only for material information the model lacks. Treat close recommendations as genuine go situations rather than reverting automatically to punts or short field goals.",
      "rationale": "Public expected-points and win-probability analyses consistently find that NFL teams surrender value by punting or kicking too often. Capturing more high-value possessions should increase scoring margin and convert some close losses into wins.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.47,
          "interval_95_low": -0.39,
          "interval_95_high": 1.33,
          "shape": "symmetric",
          "tails": "light"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The evidence supports a modest positive center, while implementation errors and model misspecification leave meaningful downside. I see no strong reason for asymmetric or heavy tails; this remains a subjective prior rather than a precise empirical estimate."
        },
        "parameters": {
          "mu": 0.47,
          "sigma": 0.439,
          "conversion_note": "Using the normal conversion: mu = 0.47 and sigma = (1.33 - (-0.39)) / (2 x 1.96) = 1.72 / 3.92 = 0.4388, reported as 0.439."
        },
        "consistency_check": "The most plausible value 0.47 is inside [-0.39, 1.33], which is symmetric about 0.47. A normal distribution has support over all real values, including harmful negative effects."
      }
    },
    {
      "bucket": "analytics",
      "type": "offensive",
      "title": "Neutral-Down Passing Shift",
      "recommendation": "Pass more often on first and second down in neutral game states, with play action and formation variation preventing the tendency from becoming transparent. Reduce the habitual early-down runs that primarily create predictable third downs.",
      "rationale": "Public EPA and pass-rate-over-expected research generally finds that passing produces more expected value than rushing, while play action does not require an established running game to work. More efficient early downs create additional first downs, scoring opportunities, and favorable late-down situations.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.63,
          "interval_95_low": -0.61,
          "interval_95_high": 1.87,
          "shape": "symmetric",
          "tails": "light"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The positive analytics case is substantial, but quarterback quality, protection, weather, and defensive adaptation could erase or reverse the benefit. This subjective prior treats those uncertainties as roughly symmetric without assigning large tail risk."
        },
        "parameters": {
          "mu": 0.63,
          "sigma": 0.633,
          "conversion_note": "Using the normal conversion: mu = 0.63 and sigma = (1.87 - (-0.61)) / (2 x 1.96) = 2.48 / 3.92 = 0.6327, reported as 0.633."
        },
        "consistency_check": "The most plausible value 0.63 is inside [-0.61, 1.87], which is symmetric about 0.63. The normal family's unbounded real support permits both positive and negative effects."
      }
    },
    {
      "bucket": "analytics",
      "type": "defensive",
      "title": "Pass-First Light-Box Defense",
      "recommendation": "Default more often to nickel or dime personnel, two-high presentations, and light boxes against spread personnel, accepting some efficient runs to suppress valuable passes and explosives. Spin safeties and vary run fits after the snap rather than telegraphing a stacked box.",
      "rationale": "Public EPA research shows that passing and explosive plays are generally more damaging than ordinary rushing gains, while additional box defenders can induce opponents to choose the more valuable pass. The likely gain is modest because defensive outcomes and personnel effects are difficult to identify causally.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.24,
          "interval_95_low": -0.98,
          "interval_95_high": 1.46,
          "shape": "symmetric",
          "tails": "light"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "Public analytics supports the pass-first premise, but evidence for a universal personnel or shell prescription is less decisive. I therefore place the subjective prior near zero with substantial, approximately symmetric uncertainty."
        },
        "parameters": {
          "mu": 0.24,
          "sigma": 0.622,
          "conversion_note": "Using the normal conversion: mu = 0.24 and sigma = (1.46 - (-0.98)) / (2 x 1.96) = 2.44 / 3.92 = 0.6224, reported as 0.622."
        },
        "consistency_check": "The most plausible value 0.24 is inside [-0.98, 1.46], which is symmetric about 0.24. Normal support is the entire real line, so the strategy can have a negative effect."
      }
    },
    {
      "bucket": "intuition",
      "type": "game_management",
      "title": "First-Half Mismatch Timeout",
      "recommendation": "Spend a first-half timeout when a high-leverage third or fourth down exposes a clear personnel, alignment, or communication failure rather than preserving every timeout reflexively. Apply a high threshold so routine discomfort does not trigger it.",
      "rationale": "Preventing one conversion or explosive play can outweigh the uncertain future value of a saved timeout. This is intuition rather than established analytics because public timeout research does not reliably value real-time mismatch recognition, and the net effect may be nearly zero.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.03,
          "interval_95_low": -0.75,
          "interval_95_high": 0.81,
          "shape": "symmetric",
          "tails": "light"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "I expect little average effect: occasionally the timeout prevents a major failure, but occasionally it is needed later. The symmetric, near-zero subjective prior reflects the weakness of the evidence."
        },
        "parameters": {
          "mu": 0.03,
          "sigma": 0.398,
          "conversion_note": "Using the normal conversion: mu = 0.03 and sigma = (0.81 - (-0.75)) / (2 x 1.96) = 1.56 / 3.92 = 0.3980, reported as 0.398."
        },
        "consistency_check": "The most plausible value 0.03 is inside [-0.75, 0.81], which is symmetric about 0.03. The normal distribution covers all signed real effects."
      }
    },
    {
      "bucket": "intuition",
      "type": "offensive",
      "title": "Abrupt Within-Drive Tempo Changes",
      "recommendation": "Change tempo abruptly within drives, especially going no-huddle after selected first downs while retaining the same personnel, instead of maintaining a predictable fast or slow identity. Pre-plan several triggers but let the quarterback cancel the tactic when communication or fatigue favors the defense.",
      "rationale": "The tactic may trap unfavorable defensive personnel, simplify coverage communication, and prevent substitutions without paying the fatigue cost of continuous hurry-up. This qualifies as intuition because public tempo studies are mixed and heavily confounded by game state, quarterback quality, and selection effects.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.17,
          "interval_95_low": -1.29,
          "interval_95_high": 1.63,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "Tempo interaction with quarterback processing, conditioning, officiating, and defensive substitution creates a meaningful chance of unexpectedly large gains or losses. A four-degree-of-freedom Student-t represents that heavy-tailed subjective uncertainty."
        },
        "parameters": {
          "nu": 4,
          "mu": 0.17,
          "sigma": 0.525,
          "conversion_note": "Using t_(0.975,4) approximately 2.78: mu = 0.17 and sigma = (1.63 - (-1.29)) / (2 x 2.78) = 2.92 / 5.56 = 0.5252, reported as 0.525. Sigma is the Student-t scale parameter, not its standard deviation."
        },
        "consistency_check": "The most plausible value and Student-t mode 0.17 is inside [-1.29, 1.63], which is symmetric about 0.17. The stated interval is approximate because the critical value was rounded, and Student-t support covers the entire real line."
      }
    },
    {
      "bucket": "intuition",
      "type": "defensive",
      "title": "Money-Down Primary-Weapon Brackets",
      "recommendation": "On selected third downs and compressed-field snaps, bracket the opponent's primary receiving threat with complementary inside-out or high-low leverage, forcing the quarterback toward secondary options. Vary the helper and disguise the bracket so the offense cannot automatically isolate the weakened area.",
      "rationale": "Removing the quarterback's trusted answer may increase hesitation, sacks, and failed conversions in the highest-leverage situations. This is intuition because public analytics lacks reliable assignment-level samples for selective double teams, and existing results are mixed and strongly affected by opponent quality and game plan.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.09,
          "interval_95_low": -1.66,
          "interval_95_high": 1.84,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "A well-designed bracket can erase decisive plays, but a quarterback who diagnoses it can exploit the coverage concession elsewhere. Those matchup-dependent outcomes justify a near-zero, heavy-tailed subjective prior."
        },
        "parameters": {
          "nu": 4,
          "mu": 0.09,
          "sigma": 0.629,
          "conversion_note": "Using t_(0.975,4) approximately 2.78: mu = 0.09 and sigma = (1.84 - (-1.66)) / (2 x 2.78) = 3.50 / 5.56 = 0.6295, reported as 0.629. Sigma is the Student-t scale parameter rather than the standard deviation."
        },
        "consistency_check": "The most plausible value and Student-t mode 0.09 is inside [-1.66, 1.84], which is symmetric about 0.09. The central interval is approximate because 2.78 is a rounded critical value, and the family has unbounded signed support."
      }
    }
  ]
}
